};
let Some(close) = rest[open..].find("];") else {
return Vec::new();
};
// 引用符で囲まれた文字列を順に拾い、2つずつ組にする
let quoted: Vec<String> = rest[open..open + close]
.split('"')
.skip(1)
.step_by(2)
.map(str::to_owned)
.collect();
quoted
.chunks(2)
.map(|pair| {
(
pair.first().cloned().unwrap_or_default(),
pair.get(1).cloned().unwrap_or_default(),
)
})
