// SPDX-License-Identifier: MIT
//! 道具の契約 ── **能力は1つ、呼び出し方は複数。**
//!
//! 戻り値は3つの欄を持つ ── `ok`（正常に終わったか）・ `findings`（検出したもの。
//! **誤りではない。** 0件でも正常である）・ `data`（機械が読む本体）。

use std::collections::BTreeMap;

use serde_json::{json, Value};

/// 引数1つ。**位置引数と旗を区別しない** ── 呼ぶ側の形は入口が決める。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Arg {
    /// 呼ぶ側が使う名前。
    pub name: &'static str,
    /// 何を渡すか。
    pub summary: &'static str,
    /// 省略できないか。
    pub required: bool,
    /// 繰り返して渡せるか。
    pub many: bool,
    /// 省略したときの値。
    pub default: Option<&'static str>,
}

impl Arg {
    /// 省略できない引数を宣言する。
    #[must_use]
    pub const fn need(name: &'static str, summary: &'static str) -> Self {
        Self {
            name,
            summary,
            required: true,
            many: false,
            default: None,
        }
    }

    /// 省略できる引数を宣言する。
    #[must_use]
    pub const fn opt(
        name: &'static str,
        summary: &'static str,
        default: Option<&'static str>,
    ) -> Self {
        Self {
            name,
            summary,
            required: false,
            many: false,
            default,
        }
    }

    /// **まとめて受ける引数を宣言する。** 繰り返すと足りていく ── 上書きにすると、
    /// 2つ目以降を黙って捨てることになる。
    #[must_use]
    pub const fn many(name: &'static str, summary: &'static str) -> Self {
        Self {
            name,
            summary,
            required: true,
            many: true,
            default: None,
        }
    }

    /// **省略できて、まとめて受ける引数を宣言する。** 0件で呼ぶことに意味がある
    /// ものは、これで宣言する ── `many` を使うと、0件の呼び方が誤用になる。
    #[must_use]
    pub const fn some(name: &'static str, summary: &'static str) -> Self {
        Self {
            name,
            summary,
            required: false,
            many: true,
            default: None,
        }
    }
}

/// 渡された引数。**入口が組み、道具が読む。**
#[derive(Debug, Clone, Default)]
#[non_exhaustive]
pub struct Given {
    values: BTreeMap<String, Vec<String>>,
}

impl Given {
    /// 1つの値を足す。
    pub fn push(&mut self, name: &str, value: String) {
        self.values.entry(name.to_owned()).or_default().push(value);
    }

    /// 名前に対する最初の値を返す。**無ければ既定を返す。**
    #[must_use]
    pub fn one<'a>(&'a self, name: &str, default: &'a str) -> &'a str {
        self.values
            .get(name)
            .and_then(|v| v.first())
            .map_or(default, String::as_str)
    }

    /// 名前に対する値が在るかを返す。
    #[must_use]
    pub fn has(&self, name: &str) -> bool {
        self.values.contains_key(name)
    }

    /// 名前に対する値を全部返す。**まとめて受ける引数のためである。**
    #[must_use]
    pub fn all(&self, name: &str) -> &[String] {
        self.values.get(name).map_or(&[], Vec::as_slice)
    }

    /// この Skill の置き場所。**呼ぶ側が `skill_root` を渡したときは、それを優先する。**
    /// 渡されなければ、実行ファイルの1つ上（`bin/` の親）とする ── 置き場所は道具の契約が
    /// `bin/` に固定するので、配布しても変わらない。どちらにも `references/` が無ければ、
    /// 試した経路を示して止める。
    ///
    /// # Errors
    ///
    /// 実行ファイルの位置を取れないとき、または `references/` が見つからないときに返す。
    pub fn skill_root(&self) -> Result<std::path::PathBuf, String> {
        if self.has("skill_root") {
            return Ok(std::path::PathBuf::from(self.one("skill_root", ".")));
        }
        let exe = std::env::current_exe()
            .map_err(|e| format!("実行ファイルの位置を取れない ── {e}"))?;
        let root = exe
            .parent()
            .and_then(std::path::Path::parent)
            .ok_or_else(|| "実行ファイルの1つ上が無い ── --skill_root で渡す".to_owned())?;
        if root.join("references").is_dir() {
            Ok(root.to_path_buf())
        } else {
            Err(format!(
                "Skill の置き場所が見つからない ── {} に references/ が無い。--skill_root で渡す",
                root.display()
            ))
        }
    }
}

/// 道具の戻り値。**印字はしない** ── 印字と終了コードは入口が持つ。
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct Outcome {
    /// 正常に終わったか。
    pub ok: bool,
    /// 検出したもの。**誤りではない。**
    pub findings: Vec<String>,
    /// 機械が読む本体。
    pub data: Value,
}

impl Outcome {
    /// 検出を伴う正常な結果を組む。
    #[must_use]
    pub fn found(findings: Vec<String>, data: Value) -> Self {
        Self {
            ok: true,
            findings,
            data,
        }
    }

    /// 誤用を組む。
    #[must_use]
    pub fn misuse(reason: String) -> Self {
        Self {
            ok: false,
            findings: vec![reason],
            data: json!({}),
        }
    }

    /// 機械が読む形へ組む。
    #[must_use]
    pub fn to_json(&self) -> Value {
        json!({ "ok": self.ok, "findings": self.findings, "data": self.data })
    }

    /// 終了コードを返す ── 0 正常 ／ 1 検出あり ／ 2 誤用。
    /// **検出を誤用と同じ番号にしない。**
    #[must_use]
    pub const fn exit_code(&self) -> i32 {
        if !self.ok {
            return 2;
        }
        if self.findings.is_empty() {
            0
        } else {
            1
        }
    }
}

/// 道具1つ。`run` は結果を返し、`human` は人向けの文を組む。
#[derive(Clone)]
#[non_exhaustive]
pub struct Tool {
    /// 呼ぶときの名前。
    pub name: &'static str,
    /// 何をするか。
    pub summary: &'static str,
    /// 受け取る引数。
    pub args: Vec<Arg>,
    /// 実体。
    pub run: fn(&Given) -> Outcome,
    /// 人向けの文を組む。
    pub human: fn(&Outcome) -> String,
}

// SPDX-License-Identifier: MIT
//! {{Skill名}} の唯一の入口。
//!
//!     {{Skill名}} <動詞> [対象…] [--json]
//!
//! **道具ごとに入口を作らない** ── 入口が増えると、呼ぶ側が形を推測することになる。
//! 許可辺は `Cargo.toml` が宣言する ── この crate は宣言だけを参照する。

use std::process::ExitCode;

use {{接頭辞}}_declare::{tools, Given, Outcome, Tool};

/// 旗と位置引数を読み、渡された引数を組む。
///
/// **旗は `--名前=値` と `--名前 値` の両方を受ける** ── 書き方を1つに強制すると、
/// 既存の手順が壊れる。**値を伴わない旗は、立っている** ── 空にすると、`--check` が
/// 黙って逆の意味になる。**次が別の旗なら、それは値ではない。**
///
/// **まとめて受ける引数は、繰り返すと足りていく。** 上書きにすると、2つ目以降を黙って
/// 捨てることになる（実測で `--layer` が1件しか残らなかった）。
fn read_args(tool: &Tool, rest: &[String]) -> Result<Given, String> {
    let mut given = Given::default();
    let mut positional: Vec<String> = Vec::new();
    let mut i = 0;
    while i < rest.len() {
        let a = &rest[i];
        if let Some(body) = a.strip_prefix("--") {
            let (key, value) = match body.split_once('=') {
                Some((k, v)) => (k.to_owned(), v.to_owned()),
                None => match rest.get(i + 1) {
                    Some(v) if !v.starts_with("--") => {
                        i += 1;
                        (body.to_owned(), v.clone())
                    }
                    _ => (body.to_owned(), "1".to_owned()),
                },
            };
            let key = key.replace('-', "_");
            // **宣言に無い旗は断る。** 黙って無視すると、打ち間違いが検出されない
            if !tool.args.iter().any(|a| a.name == key) {
                let known: Vec<&str> = tool.args.iter().map(|a| a.name).collect();
                return Err(format!(
                    "その旗は無い: --{key}（{} は {} を受ける）",
                    tool.name,
                    known.join(" ・ ")
                ));
            }
            given.push(&key, value);
        } else {
            positional.push(a.clone());
        }
        i += 1;
    }
    // **位置と旗を混ぜて渡せる。** 旗で渡したぶんを数えずに位置だけで判定すると、
    // 旗を使った呼び方が「引数が足りない」になる
    let mut free = positional.into_iter().peekable();
    for arg in &tool.args {
        if given.has(arg.name) {
            continue;
        }
        if arg.many {
            // **まとめて受ける引数は、残りの位置引数を全部取る**
            for v in free.by_ref() {
                given.push(arg.name, v);
            }
            continue;
        }
        if let Some(v) = free.next() {
            given.push(arg.name, v);
        } else if let Some(d) = arg.default {
            given.push(arg.name, d.to_owned());
        }
    }
    Ok(given)
}

fn usage(all: &[Tool]) {
    println!("道具の一覧");
    for t in all {
        let need: Vec<String> = t
            .args
            .iter()
            .map(|a| {
                if a.many {
                    format!("<{}…>", a.name)
                } else if a.required {
                    format!("<{}>", a.name)
                } else {
                    format!("[{}]", a.name)
                }
            })
            .collect();
        println!("  {} {}\n      {}", t.name, need.join(" "), t.summary);
    }
    println!("\n  どれも --json を付けると、機械が読む形で出る");
}

fn emit(out: &Outcome, as_json: bool, human: fn(&Outcome) -> String) -> ExitCode {
    if as_json {
        println!(
            "{}",
            serde_json::to_string_pretty(&out.to_json()).unwrap_or_default()
        );
    } else {
        println!("{}", human(out));
    }
    #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
    ExitCode::from(out.exit_code() as u8)
}

fn main() -> ExitCode {
    let all = tools();
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let as_json = argv.iter().any(|a| a == "--json");
    let argv: Vec<String> = argv.into_iter().filter(|a| a != "--json").collect();

    let Some(verb) = argv.first() else {
        usage(&all);
        return ExitCode::from(2);
    };
    if matches!(verb.as_str(), "-h" | "--help" | "help") {
        usage(&all);
        return ExitCode::SUCCESS;
    }
    let Some(tool) = all.iter().find(|t| t.name == verb) else {
        eprintln!("その動詞は無い: {verb} ── 一覧は help である");
        return ExitCode::from(2);
    };
    let given = match read_args(tool, &argv[1..]) {
        Ok(given) => given,
        Err(why) => {
            eprintln!("{why}");
            return ExitCode::from(2);
        }
    };
    let need: Vec<&str> = tool
        .args
        .iter()
        .filter(|a| a.required)
        .map(|a| a.name)
        .collect();
    if let Some(missing) = need.iter().find(|n| !given.has(n)) {
        eprintln!("引数が足りない: {} は {missing} を要する", tool.name);
        return ExitCode::from(2);
    }
    let out = (tool.run)(&given);
    emit(&out, as_json, tool.human)
}

